package autoplay.tests;
import java.io.*;import java.lang.classfile.*;import java.lang.classfile.instruction.*;import java.lang.reflect.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.sql.DriverManager;import java.util.*;import java.util.regex.*;
import org.l2jmobius.gameserver.cache.HtmCache;import org.l2jmobius.gameserver.config.*;import org.l2jmobius.gameserver.config.custom.MultilingualSupportConfig;import org.l2jmobius.gameserver.data.holders.AccessLevel;import org.l2jmobius.gameserver.entity.actor.Player;

/** Real private tr/html and complete Native HtmCache; no helper output or file-I/O stubs. */
public class AutoPlayLanguageCheck {
 static sun.misc.Unsafe u;static int checks;static Class<?> fixed,before;static Method tr,html,ru,oldTr;
 static void check(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
 static void field(Player p,String name,Object value)throws Exception{Field f=Player.class.getDeclaredField(name);f.setAccessible(true);f.set(p,value);}
 static Player actor(String language)throws Exception{Player p=(Player)u.allocateInstance(Player.class);field(p,"_lang",language);field(p,"_htmlPrefix",language!=null&&!language.equals("en")?"data/lang/"+language+"/":"");field(p,"_accessLevel",new AccessLevel());return p;}
 static Method privateMethod(Class<?> owner,String name,Class<?>...types)throws Exception{Method m=owner.getDeclaredMethod(name,types);m.setAccessible(true);return m;}
 static String clean(String value){return value.replaceAll("(?s)<!--.*?-->","").replaceAll("[\\t\\n]","");}
 static Map<String,Integer> placeholders(String value){Map<String,Integer> result=new TreeMap<>();Matcher m=Pattern.compile("%[a-zA-Z][a-zA-Z0-9_]*%").matcher(value);while(m.find())result.merge(m.group(),1,Integer::sum);return result;}
 static Set<String> actions(String value){Set<String> result=new TreeSet<>();Matcher m=Pattern.compile("action=\"([^\"]*)\"").matcher(value);while(m.find())result.add(m.group(1));return result;}
 static void topology(byte[] bytes)throws Exception{ClassModel model=ClassFile.of().parse(bytes);Map<String,Integer> pages=new TreeMap<>();int oldPathRequests=0;
  for(MethodModel method:model.methods())if(method.code().isPresent()){String last=null;for(CodeElement e:method.code().get()){
   if(e instanceof ConstantInstruction c&&c.constantValue()instanceof String s)last=s;
   if(e instanceof InvokeInstruction call&&call.owner().asInternalName().equals("handlers/chat/commands/voiced/AutoPlay")&&call.name().equalsString("html")){pages.merge(last,1,Integer::sum);}
   if(e instanceof InvokeInstruction call&&call.owner().asInternalName().equals("org/l2jmobius/gameserver/cache/HtmCache")&&call.name().equalsString("getHtm")&&!method.methodName().equalsString("html"))oldPathRequests++;
  }}check(pages.equals(Map.of("Main",1,"Skills",1,"Items",1,"Potion",2)),"all five actual caller requests use html; Potion twice");check(oldPathRequests==0,"no direct default-only getHtm remains at those callers");}
 static String page(Player p,String name)throws Exception{return(String)html.invoke(null,p,name);}
 public static void main(String[] args)throws Exception{try{
  boolean guarded=false;try{DriverManager.getConnection("jdbc:autoplay-language-fixture:");}catch(AssertionError error){guarded=error.getMessage().contains("Blocked world/JDBC");}catch(java.sql.SQLException error){throw new AssertionError("NoWorld/JDBC guard missing",error);}check(guarded,"active JDBC guard");
  Field unsafe=sun.misc.Unsafe.class.getDeclaredField("theUnsafe");unsafe.setAccessible(true);u=(sun.misc.Unsafe)unsafe.get(null);boolean enable=Boolean.parseBoolean(args[0]),wantRu=Boolean.parseBoolean(args[3]);String global=args[1],selected=args[2].equals("null")?null:args[2];
  GeneralConfig.HTM_CACHE=false;GeneralConfig.GM_DEBUG_HTML_PATHS=false;GeneralConfig.CHECK_HTML_ENCODING=false;ServerConfig.DATAPACK_ROOT=Path.of(".").toAbsolutePath().normalize().toFile();ServerConfig.SCRIPT_ROOT=new File(ServerConfig.DATAPACK_ROOT,"data/scripts");MultilingualSupportConfig.load();check(MultilingualSupportConfig.MULTILANG_ENABLE==enable&&MultilingualSupportConfig.MULTILANG_DEFAULT.equals(global),"real config loader honors L2HubLanguage and input MultiLang state");
  String name="handlers.chat.commands.voiced.AutoPlay";fixed=Class.forName(name);Path base=Path.of(args[4]);ClassLoader loader=new ClassLoader(AutoPlayLanguageCheck.class.getClassLoader()){@Override protected Class<?> loadClass(String n,boolean resolve)throws ClassNotFoundException{if(!n.startsWith(name))return super.loadClass(n,resolve);synchronized(getClassLoadingLock(n)){Class<?> c=findLoadedClass(n);if(c==null)try{byte[] b=Files.readAllBytes(base.resolve(n.replace('.','/')+".class"));c=defineClass(n,b,0,b.length);}catch(Exception error){throw new ClassNotFoundException(n,error);}if(resolve)resolveClass(c);return c;}}};before=loader.loadClass(name);
  tr=privateMethod(fixed,"tr",Player.class,String.class,String.class);html=privateMethod(fixed,"html",Player.class,String.class);ru=privateMethod(fixed,"isRussian",Player.class);oldTr=privateMethod(before,"tr",Player.class,String.class,String.class);Player player=actor(selected);check(Objects.equals(player.getLang(),selected),"actual Native Player.getLang is not stubbed");check(player.getHtmlPrefix().equals(enable&&"ru".equals(selected)?"data/lang/ru/":""),"actual Native Player.getHtmlPrefix follows MultiLang");check((boolean)ru.invoke(null,player)==wantRu,"real private isRussian selects runtime language");
  topology(ClassLoader.getSystemResourceAsStream(name.replace('.','/')+".class").readAllBytes());List<String> pairs=Files.readAllLines(Path.of("tr-pairs.tsv"),StandardCharsets.UTF_8);for(String line:pairs){String[] p=line.split("\t",-1);String en=new String(Base64.getDecoder().decode(p[0]),StandardCharsets.UTF_8),r=new String(Base64.getDecoder().decode(p[1]),StandardCharsets.UTF_8);check(tr.invoke(null,player,en,r).equals(wantRu?r:en),"actual explanation/caption tr routed");}
  check(oldTr.invoke(null,player,"English label","Русская подпись").equals("ru".equals(selected)?"Русская подпись":"English label"),"real baseline501 tr behavior");
  String prefix="data/html/mods/AutoPlay/",chosen=wantRu?"data/lang/ru/":"";for(String template:List.of("Main","Skills","Items","Potion","Potion")){
   String loaded=page(player,template),expected=clean(Files.readString(Path.of(chosen+prefix+template+".htm"),StandardCharsets.UTF_8));check(loaded!=null&&loaded.equals(expected),"real Native HtmCache content exact for "+template);
   String en=Files.readString(Path.of(prefix+template+".htm")),r=Files.readString(Path.of("data/lang/ru/"+prefix+template+".htm"));check(placeholders(loaded).equals(placeholders(en))&&placeholders(en).equals(placeholders(r)),"all template placeholders preserved "+template);check(actions(loaded).equals(actions(en))&&actions(en).equals(actions(r)),"all template bypasses preserved "+template);
  }
  String baseline=HtmCache.getInstance().getHtm(player,prefix+"Main.htm");if(!enable){check(baseline.contains("<title>Auto Play</title>"),"OFF/null baseline really loads EN despite defaultRU");if(wantRu)check(page(player,"Main").contains("<title>Автобой</title>"),"fixed OFF/defaultRU actually loads RU");}
  String unrelated=HtmCache.getInstance().getHtm(player,"data/html/language-fixture-other.htm");check(unrelated.equals(enable&&"ru".equals(selected)?"<html>Обычное окно</html>":"<html>Ordinary window</html>"),"unrelated Native windows retain ordinary prefix routing");
  if(enable&&global.equals("ru")){Player en=actor("en"),r=actor("ru");check(page(r,"Main").contains("Автобой")&&page(en,"Main").contains("Auto Play")&&page(r,"Main").contains("Автобой"),"real shared HtmCache has no cross-character language bleed");check(tr.invoke(null,en,"EN","РУ").equals("EN"),"explicit EN wins over globalRU");}
  check(MultilingualSupportConfig.MULTILANG_ENABLE==enable,"helpers never turn on/off global MultiLang");System.out.println("AUTOPLAY_RU_FALLBACK_CHECK_OK enable="+enable+" global="+global+" player="+selected+" expectedRU="+wantRu+" checks="+checks+" realPrivateTrHtml/NativePlayerLang/NativeHtmCacheIO;5requests4templates, no global switch or World/SQL/client");System.exit(0);
 }catch(Throwable error){error.printStackTrace();System.exit(1);}}
}
